/* 1) Keep hero from eating the screen + tighten padding */
.mm-hero {
  max-height: 70vh;           /* caps hero height on desktop */
  overflow: clip;
  padding-block: clamp(0.75rem, 3vh, 2.5rem);
}
.mm-hero .wp-block-cover,
.mm-hero img,
.mm-hero video {
  height: 100%;
  width: 100%;
  object-fit: cover;
}

/* 2) Smarter page spacing: slightly tighter on large screens */
.site-main {
  margin-inline: auto;
  padding-inline: clamp(0.75rem, 2vw, 1.5rem);
}

/* 3) Responsive post grid with auto-fit columns */
.wp-block-post-template {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 22rem), 1fr));
  gap: clamp(0.9rem, 1.6vw, 1.5rem);
}

/* 4) Feature images: consistent aspect + cover */
.wp-block-post-featured-image img {
  aspect-ratio: 1 / 1;  /* matches your block’s aspectRatio:"1" */
  width: 100%;
  height: auto;
  object-fit: cover;
  border-radius: 8px;
}

/* 5) Slightly tighter layout on wide desktops */
@media (min-width: 1200px) {
  .site-main { 
    max-width: 1200px;            /* keeps content readable */
    margin-top: clamp(0.75rem, 2vh, 2rem);
  }
  .mm-hero { 
    max-height: 60vh;             /* even shorter hero on big monitors */
    padding-block: clamp(0.5rem, 2vh, 2rem);
  }
}

/* 6) Mobile niceties */
@media (max-width: 600px) {
  .mm-hero { max-height: 55vh; }  /* avoid scroll trap on phones */
  .wp-block-post-template { gap: 1rem; }
}

/*
Theme Name: Mistyk Dark
Theme URI: https://mistykmedia.com
Author: Mistyk Media AI
Description: A modern, responsive dark mode theme with cyber-noir aesthetics.
Version: 1.0
*/

:root {
    /* Color Palette */
    --bg-dark: #121212;
    --bg-card: #1e1e1e;
    --text-main: #e0e0e0;
    --text-muted: #a0a0a0;
    --accent-primary: #8a2be2; /* Neon Violet */
    --accent-secondary: #00d4ff; /* Cyber Blue */
    --font-heading: 'Helvetica Neue', sans-serif;
    --font-body: 'Georgia', serif; /* Serif for better article readability */
}

* { box-sizing: border-box; margin: 0; padding: 0; }

body {
    background-color: var(--bg-dark);
    color: var(--text-main);
    font-family: var(--font-body);
    line-height: 1.6;
}

/* Header & Nav */
header {
    background: rgba(18, 18, 18, 0.95);
    border-bottom: 1px solid #333;
    padding: 1.5rem 0;
    position: sticky;
    top: 0;
    z-index: 100;
}

.container {
    width: 90%;
    max-width: 1200px;
    margin: 0 auto;
}

.site-branding h1 a {
    color: var(--text-main);
    text-decoration: none;
    font-family: var(--font-heading);
    text-transform: uppercase;
    letter-spacing: 2px;
    font-weight: 900;
    font-size: 1.5rem;
}

.site-branding h1 a span { color: var(--accent-primary); }

nav ul { list-style: none; display: flex; gap: 20px; }
nav a { color: var(--text-main); text-decoration: none; font-family: var(--font-heading); font-size: 0.9rem; transition: color 0.3s; }
nav a:hover { color: var(--accent-secondary); }

/* Grid Layout */
.main-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: 2rem;
    padding: 4rem 0;
}

/* Article Cards */
article.post {
    background: var(--bg-card);
    border: 1px solid #333;
    border-radius: 8px;
    padding: 2rem;
    transition: transform 0.2s, border-color 0.2s;
}

article.post:hover {
    transform: translateY(-5px);
    border-color: var(--accent-primary);
}

h2.post-title a {
    color: #fff;
    text-decoration: none;
    font-family: var(--font-heading);
    font-size: 1.4rem;
}

.post-meta { color: var(--accent-secondary); font-size: 0.8rem; margin-bottom: 1rem; display: block; text-transform: uppercase; letter-spacing: 1px; }
.excerpt { color: var(--text-muted); margin-top: 1rem; }

/* Footer */
footer { text-align: center; padding: 3rem 0; border-top: 1px solid #333; margin-top: 3rem; color: var(--text-muted); font-size: 0.9rem; }

/* Mobile Response */
@media (max-width: 768px) {
    header .container { flex-direction: column; text.section {
  padding: 4rem 0;
}

