/*
Theme Name: Mistyk Dark
Theme URI: https://mistykmedia.com
Author: Mistyk Media AI
Description: A modern, responsive dark mode theme with cyber-noir aesthetics.
Version: 1.1
*/

:root {
    --bg-dark: #121212;
    --bg-card: #1e1e1e;
    --text-main: #e0e0e0;
    --text-muted: #a0a0a0;
    --accent-primary: #8a2be2; /* Neon Violet */
    --accent-secondary: #00d4ff; /* Cyber Blue */
    --font-heading: 'Helvetica Neue', sans-serif;
    --font-body: 'Georgia', serif;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

body {
    background-color: var(--bg-dark);
    color: var(--text-main);
    font-family: var(--font-body);
    line-height: 1.6;
    -webkit-font-smoothing: antialiased;
}

/* Header */
header {
    background: rgba(18, 18, 18, 0.95);
    border-bottom: 1px solid #333;
    padding: 1.5rem 0;
    position: sticky;
    top: 0;
    z-index: 100;
    box-shadow: 0 4px 20px rgba(0,0,0,0.5);
}

.container {
    width: 92%;
    max-width: 1200px;
    margin: 0 auto;
}

.header-flex {
    display: flex; 
    justify-content: space-between; 
    align-items: center;
}

.site-branding h1 a {
    color: var(--text-main);
    text-decoration: none;
    font-family: var(--font-heading);
    text-transform: uppercase;
    letter-spacing: 2px;
    font-weight: 900;
    font-size: 1.8rem;
    text-shadow: 0 0 10px rgba(138, 43, 226, 0.3);
}

.site-branding h1 a span { color: var(--accent-primary); }

nav ul { list-style: none; display: flex; gap: 25px; margin: 0; padding: 0; }
nav a { color: var(--text-main); text-decoration: none; font-family: var(--font-heading); font-size: 0.9rem; font-weight: 600; text-transform: uppercase; transition: color 0.3s; }
nav a:hover { color: var(--accent-secondary); text-shadow: 0 0 8px var(--accent-secondary); }

/* Grid Layout */
.main-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
    gap: 2rem;
    padding: 4rem 0;
}

/* Article Cards */
article.post {
    background: var(--bg-card);
    border: 1px solid #333;
    border-radius: 12px;
    overflow: hidden;
    transition: transform 0.3s ease, box-shadow 0.3s ease;
    display: flex;
    flex-direction: column;
}

article.post:hover {
    transform: translateY(-5px);
    border-color: var(--accent-primary);
    box-shadow: 0 10px 30px rgba(0,0,0,0.5);
}

.post-image img {
    width: 100%;
    height: 200px;
    object-fit: cover;
    display: block;
    border-bottom: 1px solid #333;
}

.post-content { padding: 1.5rem; flex-grow: 1; display: flex; flex-direction: column; }

h2.post-title { margin-bottom: 0.5rem; line-height: 1.3; }
h2.post-title a {
    color: #fff;
    text-decoration: none;
    font-family: var(--font-heading);
    font-size: 1.4rem;
    transition: color 0.2s;
}
h2.post-title a:hover { color: var(--accent-secondary); }

.post-meta { color: var(--accent-primary); font-size: 0.75rem; margin-bottom: 0.5rem; display: block; text-transform: uppercase; letter-spacing: 1px; font-weight: bold; }
.excerpt { color: var(--text-muted); margin-top: 1rem; font-size: 0.95rem; margin-bottom: 1.5rem; }

.read-more {
    margin-top: auto;
    color: var(--accent-secondary);
    text-decoration: none;
    font-weight: bold;
    font-family: var(--font-heading);
    text-transform: uppercase;
    font-size: 0.85rem;
    letter-spacing: 1px;
}

/* Footer */
footer { text-align: center; padding: 3rem 0; border-top: 1px solid #333; margin-top: 3rem; color: var(--text-muted); font-size: 0.9rem; background: #0a0a0a; }

/* Mobile Response */
@media (max-width: 768px) {
    .header-flex { flex-direction: column; gap: 1rem; }
    nav ul { flex-wrap: wrap; justify-content: center; gap: 15px; }
}

