      /* Hero Section */<br />      .hero {<br />        margin-block-start: 80px;<br />        padding: 6rem 2rem;<br />        max-inline-size: 1200px;<br />        margin-inline: auto;<br />        text-align: center;<br />        position: relative;<br />      }

      .hero::before {<br />        content: "";<br />        position: absolute;<br />        inset-block-start: 50%;<br />        inset-inline-start: 50%;<br />        transform: translate(-50%, -50%);<br />        inline-size: 600px;<br />        block-size: 600px;<br />        background: radial-gradient(<br />          circle,<br />          rgba(34, 211, 238, 0.1) 0%,<br />          transparent 70%<br />        );<br />        z-index: -1;<br />        pointer-events: none;<br />      }

