      .topic-card::before {<br />        content: "";<br />        position: absolute;<br />        inset-block-start: 0;<br />        inset-inline-start: 0;<br />        inline-size: 100%;<br />        block-size: 3px;<br />        background: linear-gradient(<br />          90deg,<br />          var(--accent-cyan),<br />          var(--accent-purple)<br />        );<br />      }

      .topic-card.tech::before {<br />        background: var(--accent-cyan);<br />      }<br />      .topic-card.politics::before {<br />        background: var(--accent-purple);<br />      }<br />      .topic-card.debate::before {<br />        background: var(--accent-green);<br />      }

      .topic-tag {<br />        display: inline-block;<br />        padding: 0.25rem 0.75rem;<br />        border-radius: 20px;<br />        font-size: 0.75rem;<br />        font-weight: 600;<br />        text-transform: uppercase;<br />        margin-block-end: 1rem;<br />        font-family: "JetBrains Mono", monospace;<br />      }

