      .topic-card h3 {<br />        margin-block-end: 0.5rem;<br />        font-size: 1.25rem;<br />      }

      .topic-card p {<br />        color: var(--text-secondary);<br />        font-size: 0.9rem;<br />      }

      /* Unity Banner */<br />      .unity-banner {<br />        background: linear-gradient(<br />          135deg,<br />          var(--bg-secondary),<br />          var(--bg-primary)<br />        );<br />        border-block: 1px solid var(--border);<br />        padding: 4rem 2rem;<br />        text-align: center;<br />        margin: 3rem 0;<br />      }

      .unity-banner blockquote {<br />        font-size: 1.5rem;<br />        font-style: italic;<br />        color: var(--text-primary);<br />        max-inline-size: 800px;<br />        margin: 0 auto 1rem;<br />      }

      .unity-banner cite {<br />        color: var(--accent-cyan);<br />        font-style: normal;<br />        font-weight: 600;<br />      }

      /* Newsletter */<br />      .newsletter {<br />        padding: 5rem 2rem;<br />        background: var(--bg-secondary);<br />        text-align: center;<br />      }

      .newsletter-desc {<br />        color: var(--text-secondary);<br />        max-inline-size: 600px;<br />        margin: 0 auto 2rem;<br />      }

      .newsletter-note {<br />        margin-block-start: 1rem;<br />        font-size: 0.875rem;<br />        color: var(--text-secondary);<br />      }

      .newsletter-form {<br />        max-inline-size: 500px;<br />        margin: 2rem auto 0;<br />        display: flex;<br />        gap: 1rem;<br />        flex-wrap: wrap;<br />        justify-content: center;<br />      }

      .newsletter input {<br />        flex: 1;<br />        min-inline-size: 250px;<br />        padding: 0.875rem 1rem;<br />        background: var(--bg-primary);<br />        border: 1px solid var(--border);<br />        border-radius: 8px;<br />        color: var(--text-primary);<br />        font-size: 1rem;<br />      }

      .newsletter input:focus {<br />        outline: none;<br />        border-color: var(--accent-cyan);<br />      }

      /* Footer */<br />      footer {<br />        background: var(--bg-primary);<br />        border-block-start: 1px solid var(--border);<br />        padding: 3rem 2rem 2rem;<br />        text-align: center;<br />      }

      .social-links {<br />        display: flex;<br />        justify-content: center;<br />        gap: 1.5rem;<br />        margin-block-end: 2rem;<br />      }

      .social-links a {<br />        color: var(--text-secondary);<br />        text-decoration: none;<br />        font-size: 1.25rem;<br />        transition: color 0.3s;<br />      }

      .social-links a:hover {<br />        color: var(--accent-cyan);<br />      }

      .footer-text {<br />        color: var(--text-secondary);<br />        font-size: 0.875rem;<br />      }

      .footer-link {<br />        color: var(--accent-cyan);<br />        text-decoration: none;<br />      }

      /* Responsive */<br />      @media (max-inline-size: 768px) {<br />        .nav-links {<br />          display: none;<br />        }<br />        .mobile-menu {<br />          display: block;<br />        }<br />        .hero {<br />          padding: 4rem 1.5rem;<br />        }<br />        .mission-grid,<br />        .topics-grid {<br />          grid-template-columns: 1fr;<br />        }<br />      }<br />    </style>

